import{_ as o,o as a,c as i,a8 as t}from"./chunks/framework.BppdKxCY.js";const p=JSON.parse('{"title":"EP.03 工程化与摇树优化","description":"","frontmatter":{},"headers":[],"relativePath":"comics/EP.03-tree-shaking-build.md","filePath":"comics/EP.03-tree-shaking-build.md","lastUpdated":1793421673000}'),l={name:"comics/EP.03-tree-shaking-build.md"};function s(r,e,n,d,c,h){return a(),i("div",null,[...e[0]||(e[0]=[t('<h1 id="ep-03-工程化与摇树优化" tabindex="-1">EP.03 工程化与摇树优化 <a class="header-anchor" href="#ep-03-工程化与摇树优化" aria-label="Permalink to &quot;EP.03 工程化与摇树优化&quot;">​</a></h1><blockquote><p>对应正文：<a href="./../03-engineering">03-engineering.md</a>（模块化 / Tree Shaking / 性能指标）· 示例：<code>examples/03-01-modules/esm/main.ts</code>、<code>examples/03-02-tree-shaking.ts</code>、<code>examples/03-03-web-vitals.ts</code></p></blockquote><h2 id="剧情回顾" tabindex="-1">剧情回顾 <a class="header-anchor" href="#剧情回顾" aria-label="Permalink to &quot;剧情回顾&quot;">​</a></h2><ul><li><strong>第 1 格</strong>：标签君只用了一个 <a href="https://lodash.com/docs/4.17.21#cloneDeep" target="_blank" rel="noopener noreferrer" title="官方文档"><code>cloneDeep</code></a>，全量 <code>import _ from &#39;lodash&#39;</code> 却把整库拖进产物。</li><li><strong>第 2 格</strong>：码叔揭秘摇树：ESM 静态声明让打包器沿依赖图删除未引用导出，CJS 做不到。</li><li><strong>第 3 格</strong>：像素酱实证 <code>sideEffects</code> 副作用白名单与动态 <code>import()</code> 路由分包。</li><li><strong>第 4 格</strong>：码叔结案——优化用 Web Vitals 指标说话，警惕 barrel 文件毁掉摇树。</li></ul><h2 id="知识点拆解" tabindex="-1">知识点拆解 <a class="header-anchor" href="#知识点拆解" aria-label="Permalink to &quot;知识点拆解&quot;">​</a></h2><h3 id="第-1-格-·-全量导入的代价" tabindex="-1">第 1 格 · 全量导入的代价 <a class="header-anchor" href="#第-1-格-·-全量导入的代价" aria-label="Permalink to &quot;第 1 格 · 全量导入的代价&quot;">​</a></h3><ul><li><code>import _ from &#39;lodash&#39;</code> 把整个库打进 bundle，gzip 后依然几百 KB；</li><li>首屏 JS 体积直接影响下载、解析、执行三段时间，用户感知就是&quot;白屏久&quot;；</li><li>用 <code>webpack-bundle-analyzer</code> / <code>rollup-plugin-visualizer</code> 先看清产物构成。</li></ul><h3 id="第-2-格-·-摇树为什么依赖-esm" tabindex="-1">第 2 格 · 摇树为什么依赖 ESM <a class="header-anchor" href="#第-2-格-·-摇树为什么依赖-esm" aria-label="Permalink to &quot;第 2 格 · 摇树为什么依赖 ESM&quot;">​</a></h3><ul><li>ESM 的 <code>import</code> / <code>export</code> 是<strong>静态声明</strong>，编译期即可构建完整依赖图；</li><li>打包器从入口标记所有被引用的导出，未标记的即&quot;死代码&quot;，压缩阶段删除；</li><li>CommonJS 的 <code>require</code> 是运行时行为，路径与导出动态可变，摇树基本失效。</li></ul><h3 id="第-3-格-·-sideeffects-与分包" tabindex="-1">第 3 格 · sideEffects 与分包 <a class="header-anchor" href="#第-3-格-·-sideeffects-与分包" aria-label="Permalink to &quot;第 3 格 · sideEffects 与分包&quot;">​</a></h3><div class="language-json vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">json</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">{ </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;sideEffects&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: [</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;**/*.css&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;./src/polyfills.ts&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">] }</span></span></code></pre></div><ul><li>副作用白名单告诉打包器：白名单外的文件&quot;删掉未被引用的导出是安全的&quot;；</li><li>动态 <code>import()</code> 把代码切成独立 chunk，路由级按需加载，首屏只留公共部分；</li><li>二者配合：摇树管&quot;删得干净&quot;，分包管&quot;加载得晚&quot;。</li></ul><h3 id="第-4-格-·-用-web-vitals-说话" tabindex="-1">第 4 格 · 用 Web Vitals 说话 <a class="header-anchor" href="#第-4-格-·-用-web-vitals-说话" aria-label="Permalink to &quot;第 4 格 · 用 Web Vitals 说话&quot;">​</a></h3><ul><li><strong>LCP &lt; 2.5s</strong>（最大内容绘制）、<strong>INP &lt; 200ms</strong>（交互延迟）、<strong>CLS &lt; 0.1</strong>（累积布局偏移）；</li><li>优化闭环：测量 → 改造 → 回归对比，避免&quot;感觉变快了&quot;式的自我安慰。</li></ul><h2 id="坑点清单" tabindex="-1">坑点清单 <a class="header-anchor" href="#坑点清单" aria-label="Permalink to &quot;坑点清单&quot;">​</a></h2><blockquote><p>🔗 正文对照：<a href="./../03-engineering#_3-9-本章避坑清单">《3.9 本章避坑清单》</a></p></blockquote><ol><li>barrel 文件（<code>index.ts</code> 全量 <code>export *</code>）会让打包器无法确定引用关系，摇树失效；</li><li>依赖库选 CommonJS 版本（如 <code>lodash</code> 而非 <code>lodash-es</code>），摇不动；</li><li>给含副作用的模块错误标记 <code>sideEffects: false</code>，导致生产代码被误删。</li></ol><h2 id="自测-3-题-含答案" tabindex="-1">自测 3 题（含答案） <a class="header-anchor" href="#自测-3-题-含答案" aria-label="Permalink to &quot;自测 3 题（含答案）&quot;">​</a></h2><ol><li>摇树为什么依赖 ESM？——<strong>ESM 的 import/export 是静态声明，编译期可确定引用关系，未引用导出才能被安全删除</strong>。</li><li><code>sideEffects</code> 字段的作用？——<strong>声明哪些文件有副作用；白名单外的未引用导出允许被打包器删除</strong>。</li><li>Web Vitals 三大指标的达标线？——<strong>LCP &lt; 2.5s、INP &lt; 200ms、CLS &lt; 0.1</strong>。</li></ol>',19)])])}const g=o(l,[["render",s]]);export{p as __pageData,g as default};
